53	import org.springframework.samples.petclinic.rest.dto.PetDto;
54	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
55	import org.springframework.samples.petclinic.rest.dto.VisitDto;
56	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
57	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
58	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
59	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
60	import org.springframework.samples.petclinic.service.ClinicService;
61	import org.springframework.security.access.prepost.PreAuthorize;
62	import org.springframework.web.bind.annotation.CrossOrigin;
63	import org.springframework.web.bind.annotation.RequestMapping;
64	import org.springframework.web.bind.annotation.RestController;
65	import org.springframework.web.util.UriComponentsBuilder;
66	
67	import jakarta.servlet.http.HttpServletRequest;
68	import jakarta.transaction.Transactional;
69	
70	/**
71	 * @author Vitaliy Fedoriv
72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
86	    private static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
89	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
90	
91	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
92	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
93	
94	    /**
95	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
96	     * create with an already-seen key returns the original owner instead of creating a duplicate.
97	     */
98	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
99	
100	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
101	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
102	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
103	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    private final TelephoneNormalizer telephoneNormalizer;
114	
115	    private final AddressNormalizer addressNormalizer;
116	
117	    private final EmailNormalizer emailNormalizer;
118	
119	    private final IdentityKeyResolver identityKeyResolver;
120	
121	    private final HouseholdResolver householdResolver;
122	
123	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
124	    private final HttpServletRequest request;
125	
126	    public OwnerRestControllerV1(ClinicService clinicService,
127	                                 OwnerMapper ownerMapper,
128	                                 PetMapper petMapper,
129	                                 VisitMapper visitMapper,
130	                                 TelephoneNormalizer telephoneNormalizer,
131	                                 AddressNormalizer addressNormalizer,
132	                                 EmailNormalizer emailNormalizer,
133	                                 IdentityKeyResolver identityKeyResolver,
134	                                 HouseholdResolver householdResolver,
135	                                 HttpServletRequest request) {
136	        this.clinicService = clinicService;
137	        this.ownerMapper = ownerMapper;
138	        this.petMapper = petMapper;
139	        this.visitMapper = visitMapper;
140	        this.telephoneNormalizer = telephoneNormalizer;
141	        this.addressNormalizer = addressNormalizer;
142	        this.emailNormalizer = emailNormalizer;
143	        this.identityKeyResolver = identityKeyResolver;
144	        this.householdResolver = householdResolver;
145	        this.request = request;
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
151	        Collection<Owner> owners;
152	        if (lastName != null) {
153	            owners = this.clinicService.findOwnerByLastName(lastName);
154	        } else {
155	            owners = this.clinicService.findAllOwners();
156	        }
157	        if (owners.isEmpty()) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        owners.forEach(this::populateHouseholdMemberCount);
161	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
162	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        populateHouseholdMemberCount(owner);
173	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    /**
177	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
178	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
179	     * by the mapper alone.
180	     *
181	     * @param owner the owner to map
182	     * @return the owner DTO carrying its identity key
183	     */
184	    private OwnerDto toOwnerDto(Owner owner) {
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
187	        return ownerDto;
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
194	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
195	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
196	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
197	            if (replay != null) {
198	                return replay;
199	            }
200	        }
201	        Owner owner = createOwner(ownerFieldsDto);
202	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
203	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
204	        }
205	        return createdOwnerResponse(owner);
206	    }
207	
208	    /**
209	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
210	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
211	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
212	     * normally.
213	     *
214	     * @param idempotencyKey the client-supplied idempotency key from the request header
215	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
216	     */
217	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
218	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
219	        if (existingId == null) {
220	            return null;
221	        }
222	        Owner owner = this.clinicService.findOwnerById(existingId);
223	        if (owner == null) {
224	            return null;
225	        }
226	        populateHouseholdMemberCount(owner);
227	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
228	    }
229	
230	    /**
231	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
232	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
233	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guards then run against those derived
234	     * fields (see {@link #requireUniqueIdentity} and {@link #requireHouseholdNotDuplicate}) before the soft-duplicate
235	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
236	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
237	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
238	     *
239	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
240	     * @return the newly created, persisted owner
241	     */
242	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
243	        normalizeAndValidate(ownerFieldsDto);
244	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
245	        populateDerivedFields(owner, ownerFieldsDto);
246	        requireUniqueIdentity(owner);
247	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
248	        flagPossibleDuplicate(owner, ownerFieldsDto);
249	        this.clinicService.saveOwner(owner);
250	        populateHouseholdMemberCount(owner);
251	        auditOwnerCreated(owner);
252	        return owner;
253	    }
254	
255	    /**
256	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
257	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
258	     * canonical URL.
259	     *
260	     * @param owner the newly created, persisted owner
261	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
262	     */
263	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
264	        OwnerDto ownerDto = toOwnerDto(owner);
265	        HttpHeaders headers = new HttpHeaders();
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    /**
272	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
273	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
274	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
275	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
276	     * {@link FiscalYearResolver#fiscalYear}).
277	     *
278	     * @param owner the newly created, persisted owner, with all its derived fields already in place
279	     */
280	    private void auditOwnerCreated(Owner owner) {
281	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
282	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
283	            MembershipLevelResolver.deriveMembershipLevel(owner),
284	            owner.getCustomerCode() + "-M" + String.format("%02d",
285	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
286	    }
287	
288	    /**
289	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
290	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
291	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
292	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
293	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
294	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
295	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
296	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
297	     *
298	     * @param owner          the newly mapped owner about to be saved
299	     * @param ownerFieldsDto the incoming owner payload
300	     */
301	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
302	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
303	        owner.setNamesakeCount(countNamesakes(owner));
304	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
305	        assignHouseholdId(owner);
306	    }
307	
308	    /**
309	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
310	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
311	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
312	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
313	     * that predate this create; distinct owners therefore always receive distinct customer codes.
314	     *
315	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
316	     * @return the de-duplicated customer code, unique across all existing owners
317	     */
318	    private String deriveUniqueCustomerCode(Owner owner) {
319	        String base = identityKeyResolver.deriveCustomerCode(owner);
320	        Collection<Owner> existing = this.clinicService.findAllOwners();
321	        String candidate = base;
322	        int n = 2;
323	        while (isCustomerCodeInUse(candidate, existing)) {
324	            candidate = base + "-" + n;
325	            n++;
326	        }
327	        return candidate;
328	    }
329	
330	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
331	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
332	    }
333	
334	    /**
335	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
336	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
337	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
338	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
339	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
340	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
341	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
342	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
343	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
344	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
345	     * assigned (see {@link #requireUniqueIdentity}).
346	     *
347	     * @param ownerFieldsDto the incoming owner payload, mutated in place
348	     * @throws MissingOwnerFieldsException if any required field is missing or blank
349	     */
350	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
351	        normalizeAddress(ownerFieldsDto);
352	        validateRequiredFields(ownerFieldsDto);
353	        validatePostcode(ownerFieldsDto);
354	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
355	        ownerFieldsDto.setTelephone(telephone);
356	        requireCityHasCapacity(ownerFieldsDto.getCity());
357	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
358	        ownerFieldsDto.setRegistrationDate(registrationDate);
359	        requireDailyLimitNotReached(registrationDate);
360	        normalizeEmail(ownerFieldsDto);
361	    }
362	
363	    /**
364	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
365	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
366	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
367	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
368	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
369	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
370	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
371	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
372	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
373	     *
374	     * @param ownerFieldsDto the incoming owner payload, mutated in place
375	     */
376	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
377	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
378	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
379	        if (!line1.isEmpty()) {
380	            ownerFieldsDto.setAddressLine1(line1);
381	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
382	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
383	        }
384	        else {
385	            ownerFieldsDto.setAddressLine1(null);
386	            ownerFieldsDto.setAddressLine2(null);
387	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
388	        }
389	    }
390	
391	    /**
392	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
393	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
394	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
395	     * place so the caller can map and save it directly.
396	     *
397	     * @param ownerFieldsDto the incoming owner payload, mutated in place
398	     */
399	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
400	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
401	    }
402	
403	    /**
404	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
405	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
406	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
407	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
408	     * date is rejected.
409	     *
410	     * @param ownerFieldsDto the incoming owner payload
411	     * @return the effective registration date rolled forward onto a business day
412	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
413	     */
414	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
415	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
416	        if (effective == null) {
417	            effective = LocalDate.now();
418	        }
419	        else if (effective.isAfter(LocalDate.now())) {
420	            throw new FutureRegistrationDateException(
421	                "the registration date must not be later than the current server date");
422	        }
423	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
424	            || PUBLIC_HOLIDAYS.contains(effective)) {
425	            effective = effective.plusDays(1);
426	        }
427	        return effective;
428	    }
429	
430	    /**
431	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
432	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
433	     * further owner may be created for that day.
434	     *
435	     * @param registrationDate the adjusted business-day registration date of the owner being created
436	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
437	     */
438	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
439	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
440	            throw new DailyOwnerLimitExceededException(
441	                "the maximum number of owners for today has already been reached");
442	        }
443	    }
444	
445	    /**
446	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
447	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
448	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
449	     * warning threshold) so both express the same per-day count in one place.
450	     *
451	     * @param registrationDate the adjusted business-day registration date to count owners for
452	     * @return the number of existing owners registered on that day
453	     */
454	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
455	        return this.clinicService.findAllOwners().stream()
456	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
457	            .count();
458	    }
459	
460	    /**
461	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
462	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
463	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
464	     * reflects only owners that predate it.
465	     *
466	     * @param registrationDate the adjusted business-day registration date of the owner being created
467	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
468	     */
469	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
470	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
471	    }
472	
473	    /**
474	     * Counts how many existing owners already share the given owner's first and last name, compared
475	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
476	     * create; it is zero when the owner's name is unique.
477	     *
478	     * @param owner the newly mapped owner about to be saved
479	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
480	     */
481	    private int countNamesakes(Owner owner) {
482	        String firstName = owner.getFirstName();
483	        String lastName = owner.getLastName();
484	        return (int) this.clinicService.findAllOwners().stream()
485	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
486	                && lastName.equalsIgnoreCase(existing.getLastName()))
487	            .count();
488	    }
489	
490	    /**
491	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
492	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
493	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
494	     *
495	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
496	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
497	     * flat {@code address}.
498	     *
499	     * @param ownerFieldsDto the owner payload to validate
500	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
501	     */
502	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
503	        List<String> missingFields = new ArrayList<>();
504	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
505	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
506	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
507	        requireText(missingFields, "city", ownerFieldsDto.getCity());
508	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
509	        if (!missingFields.isEmpty()) {
510	            throw new MissingOwnerFieldsException(missingFields);
511	        }
512	    }
513	
514	    private void requireText(List<String> missingFields, String fieldName, String value) {
515	        if (value == null || value.isBlank()) {
516	            missingFields.add(fieldName);
517	        }
518	    }
519	
520	    /**
521	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
522	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
523	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
524	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
525	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
526	     *
527	     * @param ownerFieldsDto the incoming owner payload
528	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
529	     */
530	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
531	        String postcode = ownerFieldsDto.getPostcode();
532	        if (postcode == null) {
533	            return;
534	        }
535	        Region region = Region.forCity(ownerFieldsDto.getCity());
536	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
537	            throw new InvalidPostcodeException(
538	                "postcode " + postcode + " is not valid for the city's region " + region.name());
539	        }
540	    }
541	
542	    /**
543	     * Rejects creating an owner whose whole derived {@code identityKey} (see
544	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
545	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
546	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
547	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
548	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}). Owners that have been
549	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted
550	     * owner does not block the create.
551	     *
552	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
553	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
554	     */
555	    private void requireUniqueIdentity(Owner owner) {
556	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
557	        boolean inUse = this.clinicService.findAllOwners().stream()
558	            .filter(existing -> !existing.isDeleted())
559	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
560	        if (inUse) {
561	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
562	        }
563	    }
564	
565	    /**
566	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
567	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
568	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
569	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
570	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
571	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
572	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
573	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
574	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
575	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
576	     *
577	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
578	     * @param ownerFieldsDto the incoming owner payload
579	     */
580	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
581	        owner.setPossibleDuplicate(false);
582	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
583	            return;
584	        }
585	        String postcode = owner.getPostcode();
586	        if (postcode == null || postcode.isBlank()) {
587	            return;
588	        }
589	        String lastName = owner.getLastName();
590	        String telephone = owner.getTelephone();
591	        for (Owner existing : this.clinicService.findAllOwners()) {
592	            if (lastName.equalsIgnoreCase(existing.getLastName())
593	                && postcode.equals(existing.getPostcode())
594	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
595	                owner.setPossibleDuplicate(true);
596	                owner.setPossibleDuplicateOf(existing.getId());
597	                return;
598	            }
599	        }
600	    }
601	
602	    /**
603	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
604	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
605	     *
606	     * @param city the city of the owner being created
607	     * @throws OwnerCityFullException if the city already contains 50 or more owners
608	     */
609	    private void requireCityHasCapacity(String city) {
610	        long cityOwners = this.clinicService.findAllOwners().stream()
611	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
612	            .count();
613	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
614	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
615	        }
616	    }
617	
618	    /**
619	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
620	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
621	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
622	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
623	     * such owners never match one another as a household.
624	     *
625	     * @param owner the newly mapped owner about to be saved
626	     */
627	    private void assignHouseholdId(Owner owner) {
628	        String postcode = owner.getPostcode();
629	        if (postcode == null || postcode.isBlank()) {
630	            owner.setHouseholdId(null);
631	            return;
632	        }
633	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
634	    }
635	
636	    /**
637	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
638	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
639	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
640	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
641	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
642	     * without a postcode) can never be a household duplicate. Owners that have been soft-deleted (see
643	     * {@link #deleteOwner}) are ignored, so a household whose only member has been deleted does not block the create.
644	     *
645	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
646	     * @param ownerFieldsDto the incoming owner payload
647	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
648	     *                                 declare {@code sharesHousehold}
649	     */
650	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
651	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
652	            return;
653	        }
654	        String householdId = owner.getHouseholdId();
655	        if (householdId == null) {
656	            return;
657	        }
658	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
659	            .filter(existing -> !existing.isDeleted())
660	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
661	        if (sharedByExisting) {
662	            throw new DuplicateOwnerException("an owner in the same household already exists");
663	        }
664	    }
665	
666	    /**
667	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
668	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
669	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
670	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
671	     * already been saved it is itself among the members returned.
672	     *
673	     * @param owner the owner whose household members should be resolved
674	     * @return the members of the owner's household, never empty
675	     */
676	    private List<Owner> householdMembers(Owner owner) {
677	        String householdId = owner.getHouseholdId();
678	        if (householdId == null) {
679	            return List.of(owner);
680	        }
681	        return this.clinicService.findAllOwners().stream()
682	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
683	            .toList();
684	    }
685	
686	    /**
687	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
688	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
689	     * owner itself). An owner with no household is counted as a household of one.
690	     *
691	     * @param owner the owner whose household size should be resolved
692	     */
693	    private void populateHouseholdMemberCount(Owner owner) {
694	        owner.setHouseholdMemberCount(householdMembers(owner).size());
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Override
699	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
700	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
701	        if (currentOwner == null) {
702	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
703	        }
704	        validatePostcode(ownerFieldsDto);
705	        currentOwner.setAddress(ownerFieldsDto.getAddress());
706	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
707	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
708	        currentOwner.setCity(ownerFieldsDto.getCity());
709	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
710	        currentOwner.setLastName(ownerFieldsDto.getLastName());
711	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
712	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
713	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
714	        this.clinicService.saveOwner(currentOwner);
715	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
716	    }
717	
718	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
719	    @Transactional
720	    @Override
721	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
722	        Owner owner = this.clinicService.findOwnerById(ownerId);
723	        if (owner == null) {
724	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
725	        }
726	        owner.setDeleted(true);
727	        this.clinicService.saveOwner(owner);
728	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
729	    }
730	
731	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
732	    @Override
733	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
734	        Owner owner = this.clinicService.findOwnerById(ownerId);
735	        if (owner == null) {
736	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
737	        }
738	        HttpHeaders headers = new HttpHeaders();
739	        Pet pet = petMapper.toPet(petFieldsDto);
740	        owner.setId(ownerId);
741	        pet.setOwner(owner);
742	        pet.getType().setName(null);
743	        this.clinicService.savePet(pet);
744	        PetDto petDto = petMapper.toPetDto(pet);
745	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
746	            .buildAndExpand(pet.getId()).toUri());
747	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
748	    }
749	
750	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
751	    @Override
752	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
753	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
754	        if (currentOwner != null) {
755	            Pet currentPet = this.clinicService.findPetById(petId);
756	            if (currentPet != null) {
757	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
758	                currentPet.setName(petFieldsDto.getName());
759	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
760	                this.clinicService.savePet(currentPet);
761	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
762	            }
763	        }
764	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
765	    }
766	
767	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
768	    @Override
769	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
770	        HttpHeaders headers = new HttpHeaders();
771	        Visit visit = visitMapper.toVisit(visitFieldsDto);
772	        Pet pet = new Pet();
773	        pet.setId(petId);
774	        visit.setPet(pet);
775	        this.clinicService.saveVisit(visit);
776	        VisitDto visitDto = visitMapper.toVisitDto(visit);
777	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
778	            .buildAndExpand(visit.getId()).toUri());
779	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
780	    }
781	
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Override
785	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
786	        Owner owner = this.clinicService.findOwnerById(ownerId);
787	        if (owner != null) {
788	            Pet pet = owner.getPet(petId);
789	            if (pet != null) {
790	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
791	            }
792	        }
793	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
794	    }
795	}
